import{d as t,c as l,l as i,g as d}from"./index-BCkIZ7z-.js";import{_ as o}from"./_plugin-vue_export-helper-DlAUqK2U.js";const s={class:"container"},e=t({__name:"Help",setup(c){return(v,a)=>(d(),l("div",s,[...a[0]||(a[0]=[i('<h2 data-v-703b7178>帮助与使用说明</h2><section class="card" data-v-703b7178><h3 data-v-703b7178>总体说明</h3><ul data-v-703b7178><li data-v-703b7178>本应用仅负责前端展示与交互，所有文档解析、字段提取、匹配、批量处理与结果导出均由后端服务完成。</li><li data-v-703b7178>建议在开发环境通过 Vite 代理将 /api 转发至后端 Python 服务（如 http://localhost:8000）。</li></ul></section><section class="card" data-v-703b7178><h3 data-v-703b7178>使用流程</h3><ol data-v-703b7178><li data-v-703b7178>进入“字段配置”页面，维护协议字段与目标字段（可新增、编辑、删除）。</li><li data-v-703b7178>进入“提取”页面： <ul data-v-703b7178><li data-v-703b7178>选择需要提取的协议字段（支持多选），或选择一个已保存的模板。</li><li data-v-703b7178>如需复用选择，可输入模板名称并“保存为模板”。</li><li data-v-703b7178>上传协议 Word 文档，点击“开始提取”，等待后端处理完成后下载结果。</li></ul></li><li data-v-703b7178>进入“匹配”页面：进行字段拖拽/映射，保存映射（后端可写入知识库）。</li><li data-v-703b7178>进入“批量处理”页面：上传待处理数据文件，创建任务，等待并下载处理结果。</li><li data-v-703b7178>进入“知识库”页面：查看/维护知识库条目与统计。</li><li data-v-703b7178>进入“历史记录”页面：查看历史任务列表与详情。</li></ol></section><section class="card" data-v-703b7178><h3 data-v-703b7178>常见问题</h3><ul data-v-703b7178><li data-v-703b7178>未能下载结果：请确认后端已实现提取下载接口，并允许跨域或通过代理访问。</li><li data-v-703b7178>字段列表为空：请先在“字段配置”页面新增字段，或检查后端接口 /config 是否正常。</li><li data-v-703b7178>长时间无进度：后端需要维护任务队列与进度上报，请联系后端确认服务状态。</li></ul></section>',4)])]))}}),r=o(e,[["__scopeId","data-v-703b7178"]]);export{r as default};
